import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Complete real Sizzlipede, preserving both printed attacks, costs, HP, Weakness and retreat. */
public final class GeneratedRuleBatch71Test {
    static final UUID A=AttackDeckWindowTest.A,B=AttackDeckWindowTest.B;static final String ID="me5_en_009";
    static final CardDefinition CARD=BundledRules.loadCardDefinitions().find(ID).orElseThrow();static final PokemonProfile PROFILE=BundledCombatData.load().pokemon(ID).orElseThrow();
    static void check(boolean b,String s){AttackDeckWindowTest.check(b,s);}
    static ServerMatch game(int seed,int energy){var m=AttackDeckWindowTest.game(seed,CARD,PROFILE);for(int i=0;i<energy;i++){var found=m.privateView(A).hand().stream().filter(c->c.definitionId().equals("energy")).findFirst();if(found.isEmpty()){var card=m.privateView(A).deck().stream().filter(c->c.definitionId().equals("energy")).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(A,List.of(card.instanceId()));found=Optional.of(card);}m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,found.get().instanceId(),A,m.activePokemonView(A).pokemonId());}return m;}
    public static void main(String[] args){printed();for(int n:List.of(0,1,3,7,30))battle(n);controlledBurn();System.out.println("GeneratedRuleBatch71Test passed: actual80HP Sizzlipede, both printed attacks/costs, bottom7 public reveal, printed Bug Out counts, all revealed Pokemon returned, nonPokemon discard, short/empty decks and pre-KO cleanup");}
    static void printed(){check(CARD.effectSupport()==EffectSupport.SUPPORTED&&CARD.basicPokemon()&&CARD.regulationMark().equals("J")&&CARD.copyLimit()==4&&PROFILE.hitPoints()==80&&PROFILE.retreatCost()==2&&PROFILE.weaknessType()==EnergyType.WATER&&PROFILE.prizeCards()==1&&PROFILE.attacks().size()==2,"Sizzlipede printed metadata changed");var burn=PROFILE.attacks().getFirst();var bug=PROFILE.attacks().getLast();check(burn.id().equals("controlled-burn")&&burn.energyCost().equals(Map.of(EnergyType.FIRE,1))&&bug.id().equals("bug-out")&&bug.energyCost().equals(Map.of(EnergyType.COLORLESS,3))&&bug.baseDamage()==0,"Printed attacks/costs changed");AttackProgramRules.validate(bug);}
    static void battle(int n){var m=game(n*10,3);if(n<30)m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size()-n);var before=m.privateView(A).deck();var discard=m.privateView(A).discard();var window=AttackDeckWindowTest.bottom(m);int count=(int)window.stream().filter(c->c.definitionId().equals(ID)).count();m.attack(A,"bug-out");if(!window.isEmpty()){var r=m.effectCardReveal();check(r.cardIds().equals(window.stream().map(CardInstance::definitionId).toList())&&m.activePokemonView(B).damage()==0&&m.privateView(A).deck().equals(before)&&m.privateView(A).prizes().size()==6,"Actual reveal must precede damage, movement and prizes");m.acknowledgeEffectReveal(B,r.id());}check(m.lastAttack().finalDamage()==count*50,"Actual printed attack count incorrect");var drop=window.stream().filter(c->!m.cardDefinition(c.definitionId()).category().equals(CardCategory.POKEMON)).toList();var expected=new HashSet<>(before);expected.removeAll(drop);check(new HashSet<>(m.privateView(A).deck()).equals(expected)&&m.privateView(A).discard().size()==discard.size()+drop.size()&&m.privateView(A).discard().containsAll(drop),"Actual revealed cards duplicated/lost or nonmatching Pokemon discarded");if(count>=2){check(m.phase()==MatchPhase.PRIZE_SELECTION,"Lethal actual attack did not finish cleanup before KO");m.takePrizeAt(A,0);m.chooseReplacement(B,m.benchPokemonView(B).getFirst().pokemonId());}check(m.phase()==MatchPhase.TURN&&m.currentPlayer().equals(B),"Actual attack did not finish once");}
    static void controlledBurn(){var m=game(0,1);var top=m.privateView(B).deck().getLast();m.attack(A,"controlled-burn");check(m.privateView(B).discard().contains(top)&&m.lastAttack().finalDamage()==0&&m.effectCardReveal()==null&&m.currentPlayer().equals(B),"Existing Controlled Burn changed");}
}
